  int start = 0;
  int mid = 0;
  int end = 0;
  int left = 0;
  int right = 0;
  int out = 0;
  a = values;
  buf = std::vector<int>(static_cast<int>(a.size()), 0);
  width = 1;
  while ((width < static_cast<int>(a.size()))) {
    start = 0;
    while ((start < static_cast<int>(a.size()))) {
      mid = std::min((start + width), static_cast<int>(a.size()));
      end = std::min(((start + width) + width), static_cast<int>(a.size()));
      left = start;
      right = mid;
      out = start;
      while ((out < end)) {
        if (((left < mid) && ((right >= end) || (a[left] <= a[right])))) {
          buf[out] = a[left];
          left = (left + 1);
        } else {
          buf[out] = a[right];
          right = (right + 1);
        }
        out = (out + 1);
      }
      start = end;
    }
    a = buf;
    width = (width * 2);
  }
  return a;
}

