code.cpp:
#include <algorithm>
#include <cstdlib>
#include <vector>

std::vector<int> solve(const std::vector<int>& values, int target) {
  std::vector<int> dp;
  int i = 0;
  dp = std::vector<int>((target + 1), 0);
  i = 1;
  while ((i <= target)) {
    dp[i] = (dp[(i / 2)] + (i & 1));
    i = (i + 1);
  }
  return dp;
}

code.java:
class Solution {
  static int[] solve(int[] values, int target) {
    int[] dp = new int[0];
    int i = 0;
    dp = new int[(target + 1)];
    i = 1;
    while ((i <= target)) {
      dp[i] = (dp[(i / 2)] + (i & 1));
      i = (i + 1);
    }
    return dp;
  }
}
